mapper.select:
select max(sr.DATA_PERMISSION) DATA_PERMISSION
from SYS_USER_ROLE sur,
     SYS_ROLE sr,
     SYS_ROLE_ORG_PERMISSION sro
where sur.ROLE_ID = sro.ROLE_ID
  and sr.ID = sur.ROLE_ID
  and sro.ORG_CATEGORY = #{orgCategory,jdbcType=VARCHAR}
  and sro.ORG_ID = #{orgId,jdbcType=VARCHAR}
  and sur.USER_ID = #{userId,jdbcType=VARCHAR}
